package com.acme.core.application.rbac;

import com.fasterxml.jackson.databind.annotation.JsonSerialize;
import com.fasterxml.jackson.databind.ser.std.ToStringSerializer;

import java.time.LocalDateTime;
import java.util.List;

/**
 * Role management response (generated by engineering-platform 0.1.0).
 */
public record RoleResponse(
        @JsonSerialize(using = ToStringSerializer.class)
        Long id,
        String code,
        String name,
        Boolean enabled,
        String dataScope,
        @JsonSerialize(contentUsing = ToStringSerializer.class)
        List<Long> permissionIds,
        LocalDateTime createdAt) {

    public static RoleResponse of(Long id, String code, String name, Boolean enabled,
                                  String dataScope, List<Long> permissionIds, LocalDateTime createdAt) {
        return new RoleResponse(id, code, name, enabled, dataScope, permissionIds, createdAt);
    }
}
